import{_ as t,o,c as s,a0 as a}from"./chunks/framework.DVUHX04-.js";const n="/pi-extensions/assets/tools.WvgV8LkN.png",g=JSON.parse('{"title":"tools extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/tools.md","filePath":"extensions/tools.md","lastUpdated":1789775493000}'),i={name:"extensions/tools.md"};function r(l,e,c,d,h,p){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="tools-extension" tabindex="-1">tools extension <a class="header-anchor" href="#tools-extension" aria-label="Permalink to &quot;tools extension&quot;">​</a></h1><p>The <code>/tools</code> command opens a TUI list of every tool in the session. Toggle a tool to enable or disable it; the change applies immediately. The selection persists in the session (a <code>tools-config</code> entry) and is restored on session start and branch navigation, so it respects the session tree. Non-built-in tools show a tag with their origin (package name or file name), so you can see which extension provides each tool.</p><h2 id="user-only-tools-start-inactive" tabindex="-1">User-only tools start inactive <a class="header-anchor" href="#user-only-tools-start-inactive" aria-label="Permalink to &quot;User-only tools start inactive&quot;">​</a></h2><p>Two tools are <strong>user-only</strong> (CONTEXT.md, &quot;Tool exposure&quot;): the operator gets the capability as a command, and the agent tool form should not pay a context cost by default. The extension carries a default-disabled list (<code>usage_report</code>, <code>resource_toggle</code>), applied on session start and branch navigation only when the branch has no saved selection: a new session starts with the listed tools inactive, and <code>/tools</code> can enable either for that session. A saved selection always wins: once the operator makes a choice in <code>/tools</code>, it is restored exactly on start and tree navigation, and the defaults are not applied on top. The list is code, not a settings entry - the extension API has no settings reader, and one line per tool is the size of the decision (issue #72).</p><p>The command requires TUI mode; in print or RPC modes it reports that.</p><h2 id="screenshot" tabindex="-1">Screenshot <a class="header-anchor" href="#screenshot" aria-label="Permalink to &quot;Screenshot&quot;">​</a></h2><p>The list with the fixture tool set: built-in tools, a package extension tool tagged with its origin, and a local extension tool tagged with its file name.</p><p><img src="'+n+'" alt="tools list TUI"></p>',8)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
